parameters.jsCode:
function extractGeminiText(item) {
  const j = item.json || {};
  if (j.content && Array.isArray(j.content.parts)) {
    return j.content.parts.map(p => p.text || '').join('');
  }
  if (typeof j.content === 'string') return j.content;
  return '';
}
function extractAnthropicText(item) {
  const j = item.json || {};
  if (typeof j.merged_response === 'string' && j.merged_response) return j.merged_response;
  if (Array.isArray(j.content)) {
    return j.content.filter(c => c.type === 'text').map(c => c.text).join('');
  }
  if (typeof j.content === 'string') return j.content;
  return '';
}
function extractOpenAiCompatText(item) {
  const j = item.json || {};
  if (j.choices && Array.isArray(j.choices) && j.choices[0] && j.choices[0].message) {
    return j.choices[0].message.content || '';
  }
  return '';
}
// Bug fixed 2026-08-24: editorSource used to be set as soon as a tier's try block ran,
// regardless of whether that tier actually produced usable text. When
// "Editor-in-Chief Fallback (Claude)" failed on the pre-existing Anthropic credit-exhaustion
// issue (its json is {error: "Bad request..."}, no content field), extractAnthropicText()
// correctly returned '' without throwing - but editorSource still got set to 'claude_fallback',
// mislabeling a fully-failed tier as the one that answered. Confirmed live via executions
// 30624/30683/30741/30753 (2026-08-24): all 4 show editorSource: 'claude_fallback' with
// hookScore: null and verdict defaulting to the regex-miss fallback 'NEEDS REVISION' with no
// real reasoning behind it - exactly the failure mode this file's own nemotron evaluation
// warned about ("a fallback that might silently fail... blocking publication for the wrong
// reason with no visible signal that anything went wrong"). Fix: only credit a tier with
// editorSource once its extractor actually returned non-empty text; if all three tiers
// produced nothing, label it explicitly rather than defaulting to the last-tried tier's name.
let verdictText = '';
let editorSource = null;
try {
  const gptOssText = extractOpenAiCompatText($('Editor-in-Chief (GPT-OSS)').item);
  if (gptOssText) {
    verdictText = gptOssText;
    editorSource = 'gpt_oss_nim';
  }
} catch (e) { /* GPT-OSS branch didn't run in this execution path */ }
if (!verdictText) {
  try {
    const geminiText = extractGeminiText($('Editor-in-Chief Fallback (Gemini)').item);
    if (geminiText) {
      verdictText = geminiText;
      editorSource = 'gemini_fallback';
    }
  } catch (e) { /* Gemini branch didn't run */ }
}
if (!verdictText) {
  try {
    const claudeText = extractAnthropicText($('Editor-in-Chief Fallback (Claude)').item);
    if (claudeText) {
      verdictText = claudeText;
      editorSource = 'claude_fallback';
    }
  } catch (e) { /* Claude branch didn't run */ }
}
if (!editorSource) {
  editorSource = 'all_tiers_failed';
}
const verdictMatch = verdictText.match(/VERDICT:\s*(PASS|NEEDS REVISION|REJECT)/i);
const hookMatch = verdictText.match(/HOOK_SCORE:\s*(\d+)/i);
const reasonMatch = verdictText.match(/REASON:\s*(.+)/i);
return [{
  json: {
    ...$('Code in JavaScript').item.json,
    relevanceScore: $('Parse Triage').item.json.relevanceScore,
    format: $('Parse Triage').item.json.format,
    contentPillar: $('Parse Triage').item.json.contentPillar,
    objectiveTag: $('Parse Triage').item.json.objectiveTag,
    aiDraft: extractGeminiText($('Parse Content Creation').item),
    verdict: verdictMatch ? verdictMatch[1].toUpperCase() : 'NEEDS REVISION',
    hookScore: hookMatch ? parseInt(hookMatch[1], 10) : null,
    verdictReason: reasonMatch ? reasonMatch[1].trim() : '',
    editorSource,
    contentCreationSource: $('Parse Content Creation').item.json.contentCreationSource,
    auditorSource: $('Parse Auditor').item.json.auditorSource,
  },
}];

parameters.text:
=⚠️ CarIndex: Draft REJECTED by Editor-in-Chief

Title: {{ $json.title }}
Source: {{ $json.source }}
Reason: {{ $json.verdictReason }}

parameters.jsCode:
function parseJsonLoose(text) {
  const cleaned = (text || '').replace(/```json\s*/gi, '').replace(/```/g, '').trim();
  try { return JSON.parse(cleaned); } catch (e) { return null; }
}
const draft = parseJsonLoose($json.aiDraft) || {};

// Deterministic brand-name safety net, added 2026-08-27 after a live re-test proved the
// Content Creation prompt's LOCKED BRAND-NAME GLOSSARY instruction alone is NOT reliable:
// the model still mistransliterated "شيري" (Chery) as "Shari" on the original 2026-08-27
// review, then as "Sherry" on the very next re-test after the glossary rule was added -
// two different wrong spellings from the same instruction, confirming this needs a real
// find/replace safety net, not just a stronger prompt. Walks every string field in the parsed
// draft (headline, carousel_slides, platform_captions, hashtags, reel_script, everything) and
// force-corrects any of the known wrong Latin-script spellings, same "prompt alone isn't
// reliable enough, add a deterministic pass" precedent as Carousel Designer's logo-injection
// safety net. Two-pass regex: the first pass fixes standalone-word mentions ("Sherry Tiggo"),
// the second (no /i flag - relies on an explicit case list instead, since a case-insensitive
// lookahead would also treat an uppercase continuation as lowercase and never match) fixes a
// compound hashtag where the brand name runs directly into the next capitalized word with no
// separator (e.g. "#SherryTiggo7"). Arabic text is untouched - "شيري" is already correct, the
// bug only ever affects the Latin-script spelling.
const WRONG_BRAND_SPELLINGS = ['Sherry', 'Shari', 'Cherry', 'SHERRY', 'SHARI', 'CHERRY', 'sherry', 'shari', 'cherry'];
function fixBrandName(text) {
  if (typeof text !== 'string' || !text) return text;
  const alternation = WRONG_BRAND_SPELLINGS.join('|');
  return text
    .replace(new RegExp(`\\b(?:${alternation})\\b`, 'g'), 'Chery')
    .replace(new RegExp(`\\b(?:${alternation})(?=[A-Z])`, 'g'), 'Chery');
}
function fixBrandNamesDeep(value) {
  if (typeof value === 'string') return fixBrandName(value);
  if (Array.isArray(value)) return value.map(fixBrandNamesDeep);
  if (value && typeof value === 'object') {
    const out = {};
    for (const [k, v] of Object.entries(value)) out[k] = fixBrandNamesDeep(v);
    return out;
  }
  return value;
}
for (const key of Object.keys(draft)) {
  draft[key] = fixBrandNamesDeep(draft[key]);
}

// Image candidates were built well before Content Creation ran (OEM scrape or Nano Banana
// fallback - see "Identify Vehicle"/"Build Image Candidates"/"Build AI Image Candidate") and
// are long gone from $json by this point (Parse Content Creation / Merge Verdict reconstruct
// their own objects and don't carry it forward) - reach back by node name for whichever of the
// two mutually exclusive branches actually ran, same established try/catch convention used
// throughout this workflow's other fallback chains.
let imageCandidates = [];
let imageSourceType = 'none';
try {
  const n = $('Build Image Candidates').first().json;
  if (n && Array.isArray(n.imageCandidates) && n.imageCandidates.length) {
    imageCandidates = n.imageCandidates;
    imageSourceType = n.imageSourceType;
  }
} catch (e) { /* OEM branch didn't run this execution */ }
if (!imageCandidates.length) {
  try {
    const n = $('Build AI Image Candidate').first().json;
    if (n && Array.isArray(n.imageCandidates) && n.imageCandidates.length) {
      imageCandidates = n.imageCandidates;
      imageSourceType = n.imageSourceType;
    }
  } catch (e) { /* AI-generated branch didn't run this execution */ }
}
const selectedImageIndexRaw = draft.selected_image_index;
const selectedImageIndex = (Number.isInteger(selectedImageIndexRaw) && imageCandidates[selectedImageIndexRaw])
  ? selectedImageIndexRaw
  : 0;
const selectedCandidate = imageCandidates[selectedImageIndex] || null;
const imageUrl = selectedCandidate ? selectedCandidate.url : '';
const selectedImageReason = (draft.selected_image_reason || '').toString();

// Decision slide needs exactly 2 buy-if / 2 skip-if bullets. Content Creation is instructed to
// emit arrays of exactly 2, but normalize defensively here in case the model returns a bare
// string (older prompt shape) or an array with the wrong length - never let a template
// substitution downstream silently render "undefined" or drop a bullet.
function normalizeBulletPair(value, fallback) {
  let arr;
  if (Array.isArray(value)) arr = value.map(v => (v || '').toString().trim()).filter(Boolean);
  else if (typeof value === 'string' && value.trim()) arr = [value.trim()];
  else arr = [];
  while (arr.length < 2) arr.push(fallback);
  return arr.slice(0, 2);
}
const skipIfBullets = normalizeBulletPair(draft.skip_if_ar, '');
const buyIfBullets = normalizeBulletPair(draft.buy_if_ar, '');

const specFacts = (draft.spec_facts && typeof draft.spec_facts === 'object') ? draft.spec_facts : {};

return [{
  json: {
    ...$json,
    imageUrl,
    imageSourceType,
    selectedImageIndex,
    selectedImageReason,
    imageCandidateCount: imageCandidates.length,
    draftHeadline: draft.post_headline_ar || draft.post_headline_en || draft.headline_ar || draft.headline_en || draft.headline || $json.title,
    draftHeadlineEn: draft.post_headline_en || draft.post_headline_ar || draft.headline_en || draft.headline_ar || draft.headline || $json.title,
    draftSkipIf: skipIfBullets.join(' / '),
    draftSkipIfBullets: skipIfBullets,
    draftBuyIfBullets: buyIfBullets,
    draftCarouselSlides: draft.carousel_slides || [],
    draftReelScript: draft.reel_script || {},
    draftCaptionAr: draft.caption_ar || '',
    draftCaptionEn: draft.caption_en || '',
    draftHashtagsAr: draft.hashtags_ar || [],
    draftHashtagsEn: draft.hashtags_en || [],
    draftSourceCitations: draft.source_citations || [],
    draftPlatformCaptions: draft.platform_captions || {},
    draftSpecFacts: specFacts,
    draftDecisionVerdictAr: (draft.decision_verdict_ar || '').toString(),
    draftHeroStatQuoteAr: (draft.hero_stat_quote_ar || '').toString(),
    draftComparisonDeltaAr: (draft.comparison_delta_ar || '').toString(),
    draftPro1DescAr: (draft.pro_1_desc_ar || '').toString(),
    draftPro2DescAr: (draft.pro_2_desc_ar || '').toString(),
    draftPro3DescAr: (draft.pro_3_desc_ar || '').toString(),
    draftCons2DescAr: (draft.cons_2_desc_ar || '').toString(),
    draftCons3DescAr: (draft.cons_3_desc_ar || '').toString(),
    draftPro1TitleAr: (draft.pro_1_title_ar || '').toString(),
    draftPro2TitleAr: (draft.pro_2_title_ar || '').toString(),
    draftPro3TitleAr: (draft.pro_3_title_ar || '').toString(),
    draftCons2TitleAr: (draft.cons_2_title_ar || '').toString(),
    draftCons3TitleAr: (draft.cons_3_title_ar || '').toString(),
  },
}];

// Slide generation is now deterministic template substitution (see "Carousel Designer"),
// which can't fail the way per-slide LLM generation used to - the only remaining failure mode
// is the render call itself (network error to media-render, or media-render/Gotenberg erroring).
// "Render Slide to PNG" runs once per item in standard n8n per-item HTTP node order (9 in, 9
// out, order preserved), so zip it against "Carousel Designer"'s own items by index to recover
// each render's slideNumber and success/failure - this is a genuine improvement over the old
// design, which only ever tracked LLM-generation failures and had no visibility into a render
// call failing outright.
const plannedSlides = $('Carousel Designer').all();
const renderResults = $('Render Slide to PNG').all();
const renderedImageUrls = [];
const failedSlideNumbers = [];
for (let i = 0; i < plannedSlides.length; i++) {
  const slideNumber = plannedSlides[i].json.slideNumber;
  const rendered = renderResults[i] ? renderResults[i].json : {};
  if (rendered.url) {
    renderedImageUrls.push(rendered.url);
  } else {
    failedSlideNumbers.push(slideNumber);
  }
}
return [{
  json: {
    ...$('Merge Carousel Inputs').item.json,
    renderedImageUrls,
    failedSlideNumbers,
    totalSlides: plannedSlides.length,
  },
}];

const staticData = $getWorkflowStaticData('global');
const updates = $json.result || [];
let maxUpdateId = staticData.telegramUpdateOffset ? staticData.telegramUpdateOffset - 1 : -1;
const replies = [];
for (const update of updates) {
  if (update.update_id > maxUpdateId) maxUpdateId = update.update_id;
  const msg = update.message;
  if (!msg || !msg.reply_to_message) continue;
  replies.push({
    json: {
      replyToMessageId: msg.reply_to_message.message_id,
      replyText: (msg.text || '').trim().toUpperCase(),
    },
  });
}
staticData.telegramUpdateOffset = maxUpdateId + 1;
return replies;

// Rule-based relevance pre-filter, run before the Triage (Gemini) call so obviously
// off-topic articles never cost an LLM call. Deliberately conservative (few false
// rejects): anything mentioning a known brand or a price/launch/comparison/market-data
// signal still goes to Triage for real scoring. Only rejects items with NONE of that.
// Duplicate detection is NOT reimplemented here - "Is Duplicate" / "IF Not Duplicate"
// upstream already handles that; this node only adds the relevance check.
//
// BRANDS list copied verbatim from "Code in JavaScript" (the dedupe key normalizer) so
// brand-relevance stays anchored to the one list already used elsewhere in this
// pipeline, not a second copy that could drift. Relevance keyword groups (price/
// launch/comparison/market-data) are a regex approximation of the relevance criteria
// already written into the "Triage" node's system prompt ("10 = highly relevant:
// pricing, launches, comparisons, EV news, market data; 1 = irrelevant: motorsport
// gossip, unrelated markets, opinion pieces with no data") - keep both in sync with
// that prompt if it changes.
const BRANDS = [
  'toyota','hyundai','kia','chery','mg','byd','geely','jetour','changan','gac','nissan',
  'chevrolet','peugeot','citroen','citroën','renault','fiat','skoda','volkswagen','vw','bmw',
  'mercedes','audi','honda','mazda','suzuki','mitsubishi','ford','jeep','opel','seat','cupra',
  'exeed','deepal','gwm','haval','tesla','volvo','lexus','infiniti','genesis','dongfeng','jac',
  'baic','zeekr','xpeng','nio','im','li','aito','porsche','land rover','range rover','jaguar',
  'bugatti','ferrari','lamborghini','maserati','bentley','rolls-royce','cadillac','buick',
  'mansour','contactcars'
];

const PRICE_RE = /\b(egp|e£|price[sd]?|pricing|starts?\s+at|msrp|جنيه|سعر|أسعار)\b/i;
const LAUNCH_RE = /\b(launch(es|ed|ing)?|unveil(s|ed|ing)?|debut(s|ed|ing)?|reveal(s|ed|ing)?|arrives?|now\s+available|إطلاق|كشف)\b/i;
const COMPARE_RE = /\bvs\.?\b|\bcompar(e|es|ed|ison)\b|مقارنة/i;
const MARKET_RE = /\b(ev|electric\s+vehicle|kwh|battery\s+range|sales\s+figures?|market\s+share|registrations?|كهربائية|مبيعات)\b/i;
const MOTORSPORT_RE = /\b(formula\s?1|f1\s+grand\s+prix|motogp|nascar|wrc\s+rally|rally\s+stage|qualifying\s+results?|pole\s+position|podium\s+finish)\b/i;

const output = [];
for (const item of $input.all()) {
  const title = item.json.title || '';
  const snippet = item.json.contentSnippet || '';
  const text = `${title} ${snippet}`;
  const lower = text.toLowerCase();

  const brandHit = BRANDS.some(b => lower.includes(b));
  const signalHit = PRICE_RE.test(text) || LAUNCH_RE.test(text) || COMPARE_RE.test(text) || MARKET_RE.test(text);
  const passesFilter = brandHit || signalHit;

  let filterReason = '';
  if (!passesFilter) {
    filterReason = MOTORSPORT_RE.test(text)
      ? 'no brand/relevance signal found (motorsport-only content)'
      : 'no brand/relevance signal found (no brand, price, launch, comparison, or market-data keyword)';
  }

  output.push({
    json: {
      ...item.json,
      passesFilter,
      filterReason,
    },
  });
}
return output;

// Builds the /render scenes[] array from Content Creation's reel_script
// (draftReelScript: {hook_ar, hook_en, body_ar, body_en, cta_ar, cta_en, duration_seconds}).
//
// English-only captions for now: media-render's ffmpeg drawtext uses Latin-only fonts
// (SpaceGrotesk/Inter/JetBrainsMono - see FONT_HEADING/FONT_BODY/FONT_MONO in app.py), so
// Arabic text would not render correctly there, unlike the Carousel Designer's
// Gotenberg/Chromium HTML path, which shapes Arabic natively. This is a known gap, not an
// oversight - flagged for a decision (add an Arabic-capable font, or pre-render captions as
// PNG overlays via Gotenberg like the carousel does) before this ships with Arabic captions.
//
// Same hero image (imageUrl, set earlier by Set Sourced Image / Set Generated Image) is
// reused across all scenes with a Ken Burns zoom - there's only one sourced/generated image
// per post, unlike the carousel's per-slide visuals.
const reel = $json.draftReelScript || {};
const totalDuration = Number(reel.duration_seconds) > 0 ? Number(reel.duration_seconds) : 15;

const beats = [
  { text: reel.hook_en || '' },
  { text: reel.body_en || '' },
  { text: reel.cta_en || '' },
].filter(b => b.text);

const MIN_SCENE_SECONDS = 2;
const totalChars = beats.reduce((sum, b) => sum + b.text.length, 0) || 1;

let scenes = beats.map(b => ({
  image_url: $json.imageUrl,
  text: b.text,
  duration_sec: Math.max(MIN_SCENE_SECONDS, Math.round((b.text.length / totalChars) * totalDuration)),
}));

if (scenes.length === 0) {
  scenes = [{ image_url: $json.imageUrl, text: $json.draftHeadline || '', duration_sec: totalDuration }];
}

return [{
  json: {
    ...$json,
    videoScenes: scenes,
  },
}];

// Carries the original item forward regardless of whether the /render call succeeded
// (response has "url") or failed (onError: continueRegularOutput leaves an "error" field
// and drops everything else n8n would normally carry on $json) - mirrors the
// $('NodeName').item.json rehydration pattern used elsewhere in this workflow (e.g. "Is
// Duplicate", "Set Generated Image") for the same reason.
return [{
  json: {
    ...$('Build Video Scenes').item.json,
    videoUrl: $json.url || null,
    videoRenderError: $json.error ? String($json.error) : null,
  },
}];

