parameters.jsCode:
function extractNimText(item) {
  const j = item.json || {};
  if (Array.isArray(j.choices) && j.choices[0] && j.choices[0].message) {
    return j.choices[0].message.content || '';
  }
  return '';
}
function parseJsonLoose(text) {
  const cleaned = (text || '').replace(/```json\s*/gi, '').replace(/```/g, '').trim();
  try { return JSON.parse(cleaned); } catch (e) { return null; }
}
const text = extractNimText($input.item);
const parsed = parseJsonLoose(text) || {};
const make = (parsed.make || '').toString().trim();
const model = (parsed.model || '').toString().trim();
return [{
  json: {
    ...$('Code in JavaScript').item.json,
    vehicleMake: make,
    vehicleModel: model,
    vehicleModelYear: (parsed.model_year || '').toString().trim(),
    vehicleTrimHint: (parsed.trim_hint || '').toString().trim(),
    vehicleIdentified: !!(make && model),
  },
}];

// Reuses the OEM domain registry from tools/image_sourcing/oem_image_scraper.py (design-
// reference tool, not previously wired into the pipeline - see CLAUDE.md). Kept in sync
// manually since n8n Code nodes can't import that module, same precedent as the BRANDS array
// duplicated in "Code in JavaScript" / "Relevance Pre-Filter".
const OEM_DOMAINS = {
  byd: { eg: 'byd.com.eg', global: 'byd.com' },
  geely: { eg: 'geely-egypt.com', global: 'geely.com' },
  chery: { eg: 'cheryegypt.com', global: 'chery.com' },
  mg: { eg: 'mgmotor-eg.com', global: 'mg.co.uk' },
  jac: { eg: 'jac-egypt.com', global: 'jac.com.cn' },
  hyundai: { eg: 'hyundai-egypt.com', global: 'hyundai.com' },
  toyota: { eg: 'toyotaegypt.com.eg', global: 'toyota.com' },
  nissan: { eg: 'nissan-egypt.com', global: 'nissan-global.com' },
  kia: { eg: 'kia.com.eg', global: 'kia.com' },
  seat: { eg: 'seat-eg.com', global: 'seat.com' },
  cupra: { eg: 'cupraofficial-eg.com', global: 'cupraofficial.com' },
  opel: { eg: 'opel-eg.com', global: 'opel.com' },
  volvo: { eg: 'volvocars-eg.com', global: 'volvocars.com' },
  changan: { eg: 'changan-eg.com', global: 'globalchangan.com' },
  xpeng: { eg: 'xpeng.com', global: 'xpeng.com' },
  avatr: { eg: 'avatr.com', global: 'avatr.com' },
};
const make = $json.vehicleMake || '';
const model = $json.vehicleModel || '';
const base = `${make} ${model}`.trim();
const domains = OEM_DOMAINS[make.toLowerCase()] || {};
const queries = [
  { market: 'eg', query: domains.eg ? `${base} site:${domains.eg}` : `${base} مصر السعر official Egypt dealer` },
  { market: 'global', query: domains.global ? `${base} site:${domains.global}` : `${base} official press photo` },
];
return queries.map(q => ({ json: { ...$json, oemQueryMarket: q.market, oemQuery: q.query } }));

const html = ($json.data || '').toString();
const m = html.match(/vqd=['"]?([\d-]+)['"]?/);
return {
  json: {
    market: $('Build OEM Queries').item.json.oemQueryMarket,
    query: $('Build OEM Queries').item.json.oemQuery,
    vqd: m ? m[1] : '',
  },
};

function looksLikeImageUrl(url) {
  if (!url) return false;
  const clean = url.split('?')[0].split('#')[0].toLowerCase();
  return /\.(jpg|jpeg|png|webp)$/.test(clean) || url.toLowerCase().includes('image');
}
const modelToken = ($('Parse Vehicle ID').first().json.vehicleModel || '').toLowerCase().replace(/[^a-z0-9]/g, '');
const metaItems = $('Extract VQD').all();
const searchItems = $input.all();
const candidates = [];
for (let i = 0; i < searchItems.length; i++) {
  const meta = metaItems[i] ? metaItems[i].json : {};
  const body = searchItems[i].json || {};
  const results = Array.isArray(body.results) ? body.results : [];
  let taken = 0;
  for (const r of results) {
    if (taken >= 5) break;
    const url = r.image;
    if (!url || !looksLikeImageUrl(url)) continue;
    const haystack = ((r.url || '') + url).toLowerCase().replace(/[^a-z0-9]/g, '');
    const modelMatch = !!(modelToken && haystack.includes(modelToken));
    candidates.push({
      json: {
        url,
        pageUrl: r.url || '',
        title: r.title || '',
        width: r.width || 0,
        height: r.height || 0,
        market: meta.market || '',
        query: meta.query || '',
        modelMatchConfidence: modelMatch ? 'high' : 'low',
      },
    });
    taken++;
  }
}
return candidates.length ? candidates : [{ json: { noOemCandidates: true } }];

const raw = (($json.oemCandidates || []).filter(c => c.url));
// High-confidence (model name actually found in the page/image URL) first, then the rest -
// see CLAUDE.md for why this matters: a bare site: query alone returned other models' pages
// mixed in for JAC's Egypt site (JS4/S7 pages showed up in a "JAC JS2" query).
raw.sort((a, b) => (b.modelMatchConfidence === 'high' ? 1 : 0) - (a.modelMatchConfidence === 'high' ? 1 : 0));
const capped = raw.slice(0, 6);
const imageCandidates = capped.map((c, i) => ({
  index: i,
  url: c.url,
  title: c.title || '',
  market: c.market,
  pageUrl: c.pageUrl,
  modelMatchConfidence: c.modelMatchConfidence,
}));
return [{
  json: {
    ...$('Parse Vehicle ID').first().json,
    imageCandidates,
    imageSourceType: 'oem',
  },
}];

return [{
  json: {
    ...$('Parse Vehicle ID').first().json,
    imageCandidates: [{
      index: 0,
      url: $json.url,
      title: 'AI-generated placeholder (no usable OEM image found)',
      market: 'ai-generated',
      pageUrl: '',
      modelMatchConfidence: 'n/a',
    }],
    imageSourceType: 'ai_generated',
  },
}];

// Competitor comparison images have no existing source in this pipeline - the OEM image
// scraper (Identify Vehicle/Build OEM Queries/...) only sources the article's own vehicle,
// never named competitors. Reuses the same DDG image-search technique (see "Build OEM
// Queries"/"DDG Get VQD"/"DDG Image Search"/"Parse OEM Candidates") rather than a new
// mechanism.
//
// Tightened 2026-08-27: was a blind generic "<name> official press photo" query with no site
// scoping at all, unlike the subject vehicle's own OEM_DOMAINS-scoped search - a confirmed real
// quality gap (a Hyundai Tucson comparison photo came back generic/wrong-looking). Now reuses
// the same OEM_DOMAINS registry (duplicated here, same "n8n Code nodes can't import a shared
// module" precedent as Build OEM Queries / Code in JavaScript / Relevance Pre-Filter - keep all
// four in sync if this list changes) to scope the competitor's own query to its OEM domain when
// the competitor's brand is covered, same as the subject car gets. Falls back to the original
// generic query when the competitor's brand isn't in the registry - never worse than before.
const OEM_DOMAINS = {
  byd: { eg: 'byd.com.eg', global: 'byd.com' },
  geely: { eg: 'geely-egypt.com', global: 'geely.com' },
  chery: { eg: 'cheryegypt.com', global: 'chery.com' },
  mg: { eg: 'mgmotor-eg.com', global: 'mg.co.uk' },
  jac: { eg: 'jac-egypt.com', global: 'jac.com.cn' },
  hyundai: { eg: 'hyundai-egypt.com', global: 'hyundai.com' },
  toyota: { eg: 'toyotaegypt.com.eg', global: 'toyota.com' },
  nissan: { eg: 'nissan-egypt.com', global: 'nissan-global.com' },
  kia: { eg: 'kia.com.eg', global: 'kia.com' },
  seat: { eg: 'seat-eg.com', global: 'seat.com' },
  cupra: { eg: 'cupraofficial-eg.com', global: 'cupraofficial.com' },
  opel: { eg: 'opel-eg.com', global: 'opel.com' },
  volvo: { eg: 'volvocars-eg.com', global: 'volvocars.com' },
  changan: { eg: 'changan-eg.com', global: 'globalchangan.com' },
  xpeng: { eg: 'xpeng.com', global: 'xpeng.com' },
  avatr: { eg: 'avatr.com', global: 'avatr.com' },
};
const specFacts = ($json.draftSpecFacts && typeof $json.draftSpecFacts === 'object') ? $json.draftSpecFacts : {};
const slots = [
  { slot: 'comp1', name: (specFacts.competitor_1_name || '').toString().trim() },
  { slot: 'comp2', name: (specFacts.competitor_2_name || '').toString().trim() },
];
function buildQuery(name) {
  if (!name) return 'car';
  const brandWord = name.split(/\s+/)[0].toLowerCase();
  const domain = OEM_DOMAINS[brandWord];
  // prefer the global OEM domain for a competitor (this isn't the article's own subject car,
  // so there's no strong reason to prefer the Egypt-market domain specifically - global sites
  // more consistently carry a clean studio/press exterior shot).
  if (domain && domain.global) return `${name} site:${domain.global}`;
  return `${name} official press photo`;
}
return slots.map(s => ({
  json: {
    ...$json,
    competitorSlot: s.slot,
    competitorName: s.name,
    hasCompetitorName: !!s.name,
    competitorQuery: buildQuery(s.name),
  },
}));

const html = ($json.data || '').toString();
const m = html.match(/vqd=['"]?([\d-]+)['"]?/);
return {
  json: {
    competitorSlot: $('Build Competitor Image Queries').item.json.competitorSlot,
    competitorName: $('Build Competitor Image Queries').item.json.competitorName,
    hasCompetitorName: $('Build Competitor Image Queries').item.json.hasCompetitorName,
    query: $('Build Competitor Image Queries').item.json.competitorQuery,
    vqd: m ? m[1] : '',
  },
};

// Tightened 2026-08-27: previously took the FIRST image-looking DDG result unconditionally,
// with zero quality check - the confirmed real defect (a generic/wrong-looking Hyundai Tucson
// comparison photo). Now applies the same discipline "Parse OEM Candidates" already uses for
// the subject vehicle's own photo: prefer a result whose page URL/image URL actually contains
// the competitor's model-name token, and require a minimum image size when DDG reports
// dimensions (filters out icons/placeholders/thumbnails) - falling back gracefully, never
// leaving the slot empty just because no candidate hits every bar.
function looksLikeImageUrl(url) {
  if (!url) return false;
  const clean = url.split('?')[0].split('#')[0].toLowerCase();
  return /\.(jpg|jpeg|png|webp)$/.test(clean) || url.toLowerCase().includes('image');
}
const MIN_DIMENSION = 400;
function modelTokenFor(name) {
  // drop the brand word (first token), keep the rest as the distinguishing model token -
  // e.g. "Hyundai Tucson" -> "tucson", "Kia Sportage" -> "sportage".
  const parts = (name || '').toString().trim().split(/\s+/);
  return parts.slice(1).join('').toLowerCase().replace(/[^a-z0-9]/g, '');
}
const metaItems = $('Competitor Extract VQD').all();
const searchItems = $input.all();
const result = { comp1ImageUrl: '', comp2ImageUrl: '' };
for (let i = 0; i < searchItems.length; i++) {
  const meta = metaItems[i] ? metaItems[i].json : {};
  if (!meta.hasCompetitorName) continue;
  const modelToken = modelTokenFor(meta.competitorName);
  const body = searchItems[i].json || {};
  const results = Array.isArray(body.results) ? body.results : [];
  const candidates = results
    .filter(r => looksLikeImageUrl(r.image))
    .slice(0, 8)
    .map(r => {
      const haystack = ((r.url || '') + r.image).toLowerCase().replace(/[^a-z0-9]/g, '');
      const modelMatch = !!(modelToken && haystack.includes(modelToken));
      const hasDimensions = !!(r.width && r.height);
      const bigEnough = !hasDimensions || (r.width >= MIN_DIMENSION && r.height >= MIN_DIMENSION);
      return { url: r.image, modelMatch, bigEnough, hasDimensions };
    });
  // preference order: model-match AND big enough > model-match alone > big-enough alone >
  // first candidate regardless (never leave the slot empty if any image-looking result exists).
  const best =
    candidates.find(c => c.modelMatch && c.bigEnough) ||
    candidates.find(c => c.modelMatch) ||
    candidates.find(c => c.bigEnough) ||
    candidates[0];
  if (best) {
    if (meta.competitorSlot === 'comp1') result.comp1ImageUrl = best.url;
    if (meta.competitorSlot === 'comp2') result.comp2ImageUrl = best.url;
  }
}
return [{ json: result }];

// Added 2026-08-27: makes Auditor's unsourced/superlative-claim finding a hard gate
// instead of an advisory note that reached Pending/Telegram unchanged (confirmed real
// defect on the 2026-08-27 Tiggo 7 Pro live-pipeline review). Auditor's own prompt (both
// the NIM primary and the Gemini fallback, kept in sync) now ends its response with a
// machine-parseable "HARD_FAIL: true/false" line - parsed here, same regex-extraction
// style Merge Verdict already uses for EIC's VERDICT:/HOOK_SCORE:/REASON: lines.
// On total audit failure (auditorSource === 'all_tiers_failed', no real audit ran at
// all - see architecture.md §8 item 9, a separate known gap) this deliberately does NOT
// hard-fail - that would block every draft whenever both Auditor tiers happen to be
// down, a much bigger behavior change than this fix is scoped to make.
const auditorJson = $('Parse Auditor').item.json;
const text = (auditorJson.content && Array.isArray(auditorJson.content.parts))
  ? auditorJson.content.parts.map(p => p.text || '').join('')
  : '';
const match = text.match(/HARD_FAIL:\s*(true|false)/i);
let auditorHardFail = (auditorJson.auditorSource !== 'all_tiers_failed') && !!match && match[1].toLowerCase() === 'true';
const hardFailReasons = [];
if (auditorHardFail) hardFailReasons.push('Auditor HARD_FAIL: true (see audit text below)');

// Added 2026-08-29: deterministic duplicate-boilerplate check across platform_captions.
// Confirmed real defect on the 2026-08-27 review: the same generic tagline ("Need 4WD?")
// appeared verbatim across all six platform captions instead of platform-tailored copy.
// This is a mechanically checkable defect (exact line repetition) - checked here in code
// rather than left entirely to the LLM's own judgment, same "don't trust a prompt
// instruction alone for something code can verify directly" precedent as Content
// Creation's brand-name safety net (see 2026-08-27/28 section above). Runs independently
// of the Auditor HARD_FAIL line above - either signal alone is enough to block.
function parseJsonLoose(t) {
  const cleaned = (t || '').replace(/```json\s*/gi, '').replace(/```/g, '').trim();
  try { return JSON.parse(cleaned); } catch (e) { return null; }
}

// Added 2026-08-29 (item 8): recomputes the Comparison slide's own callout numbers
// (comparison_delta_ar) against the structured spec_facts sitting right above it on the
// same slide, and hard-fails on a mismatch beyond rounding tolerance. Confirmed real defect
// on execution 38526: the callout claimed "~200,000"/"~250,000 EGP cheaper" and "10-15% less
// power" while spec_facts' own numbers work out to 275,000/325,000 EGP and +7.4%/-3.3% power
// (wrong-signed for one competitor, overstated ~3-4x for the other) - the free-text summary
// was never recomputed from the structured numbers next to it. Same "don't trust a free-text
// field to stay consistent with structured facts, verify it in code" precedent as the
// duplicate-caption check above - deliberately does NOT try to parse direction/wording
// (e.g. "less" vs "more"), only magnitude, since direction-parsing on free Arabic text is
// far less reliable than a number comparison and the real defect found here was primarily a
// magnitude mismatch (bad enough on its own to flag).
function checkComparisonArithmetic(specFacts, comparisonDeltaAr) {
  const reasons = [];
  if (!specFacts || !comparisonDeltaAr) return reasons;
  const numOf = (v) => {
    const n = parseFloat(String(v).replace(/[,،\s]/g, ''));
    return Number.isFinite(n) ? n : null;
  };
  const price = numOf(specFacts.price_egp);
  const power = numOf(specFacts.power_hp);
  const priceMatches = [...comparisonDeltaAr.matchAll(/\d{1,3}(?:[,،]\d{3})+|\d{4,}/g)]
    .map(m => parseFloat(m[0].replace(/[,،]/g, '')))
    .filter(n => Number.isFinite(n) && n >= 1000);
  const pctMatches = [...comparisonDeltaAr.matchAll(/(\d{1,3})\s*-?\s*(\d{0,3})\s*(?:%|٪)/g)]
    .flatMap(m => [parseFloat(m[1]), m[2] ? parseFloat(m[2]) : null])
    .filter(n => n !== null && Number.isFinite(n));
  const priceWithinTolerance = (claimed, real) => Math.abs(claimed - real) <= Math.max(15000, real * 0.15);
  const pctWithinTolerance = (claimed, real) => Math.abs(claimed - real) <= Math.max(2, real * 0.25);
  const realPriceDeltas = [];
  const realPowerPcts = [];
  for (const idx of [1, 2]) {
    const compPrice = numOf(specFacts[`competitor_${idx}_price_egp`]);
    const compPower = numOf(specFacts[`competitor_${idx}_power_hp`]);
    const compName = specFacts[`competitor_${idx}_name`] || `competitor ${idx}`;
    realPriceDeltas.push({ compName, value: (price !== null && compPrice !== null) ? Math.abs(compPrice - price) : null });
    realPowerPcts.push({ compName, value: (power !== null && compPower) ? Math.abs((power - compPower) / compPower * 100) : null });
  }
  function checkSet(claimedList, realList, withinFn, label, unit) {
    if (claimedList.length === realList.length && realList.every(r => r.value !== null)) {
      realList.forEach((r, i) => {
        if (!withinFn(claimedList[i], r.value)) {
          reasons.push(`Comparison slide callout ${label} vs ${r.compName} doesn't match spec_facts: claimed ~${claimedList[i]}${unit}, real is ~${r.value.toFixed(1)}${unit}.`);
        }
      });
    } else {
      realList.forEach(r => {
        if (r.value === null || !claimedList.length) return;
        if (!claimedList.some(c => withinFn(c, r.value))) {
          reasons.push(`Comparison slide callout ${label} vs ${r.compName} doesn't match spec_facts: real is ~${r.value.toFixed(1)}${unit}, no claimed figure is within tolerance.`);
        }
      });
    }
  }
  if (priceMatches.length) checkSet(priceMatches, realPriceDeltas, priceWithinTolerance, 'price gap', ' EGP');
  if (pctMatches.length) checkSet(pctMatches, realPowerPcts, pctWithinTolerance, 'power percentage', '%');
  return reasons;
}

try {
  const ccJson = $('Parse Content Creation').item.json;
  const ccText = (ccJson.content && Array.isArray(ccJson.content.parts))
    ? ccJson.content.parts.map(p => p.text || '').join('')
    : '';
  const draft = parseJsonLoose(ccText) || {};
  const pc = draft.platform_captions || {};
  function linesOf(blob) {
    return (blob || '').split('\n').map(l => l.trim()).filter(l => l.length > 12);
  }
  for (const lang of ['ar', 'en']) {
    const blobs = [
      pc.instagram && pc.instagram[`caption_${lang}`],
      pc.facebook && pc.facebook[`caption_${lang}`],
      pc.x && pc.x[`caption_${lang}`],
      pc.threads && pc.threads[`caption_${lang}`],
      pc.tiktok && pc.tiktok[`caption_${lang}`],
      pc.youtube && pc.youtube[`description_${lang}`],
    ];
    const lineCounts = {};
    for (const blob of blobs) {
      const seenInThisBlob = new Set();
      for (const line of linesOf(blob)) {
        if (seenInThisBlob.has(line)) continue;
        seenInThisBlob.add(line);
        lineCounts[line] = (lineCounts[line] || 0) + 1;
      }
    }
    for (const [line, count] of Object.entries(lineCounts)) {
      if (count >= 2) {
        auditorHardFail = true;
        hardFailReasons.push(`Duplicate boilerplate line repeated across ${count} of the 6 platform captions (${lang}): "${line}"`);
      }
    }
  }

  const arithmeticIssues = checkComparisonArithmetic(draft.spec_facts, draft.comparison_delta_ar);
  if (arithmeticIssues.length) {
    auditorHardFail = true;
    hardFailReasons.push(...arithmeticIssues);
  }
} catch (e) {
  // Content Creation branch didn't run, or the draft didn't parse - skip these checks rather
  // than hard-failing on a parsing problem unrelated to what they actually target.
}

return [{
  json: {
    auditorHardFail,
    auditorText: text,
    hardFailReasons,
  },
}];

