function extractGeminiText(item) {
  const j = item.json || {};
  if (j.content && Array.isArray(j.content.parts)) {
    return j.content.parts.map(p => p.text || '').join('');
  }
  if (typeof j.content === 'string') return j.content;
  return '';
}
function extractNimText(item) {
  const j = item.json || {};
  if (Array.isArray(j.choices) && j.choices[0] && j.choices[0].message) {
    return j.choices[0].message.content || '';
  }
  return '';
}
// Bug fixed 2026-08-24 (same root cause as Merge Verdict's editorSource fix, same day):
// contentCreationSource used to be set as soon as the Gemini fallback's try block ran,
// regardless of whether extractGeminiText() actually returned usable text. When
// "Content Creation Fallback (Gemini)" fails (its json is {error: "..."}, no content field —
// confirmed live via executions 30972/30978 on 2026-08-24, Gemini's burst rate limit), the old
// code still labeled it contentCreationSource: 'gemini_fallback', masking a fully-failed
// fallback as a success with no visible signal. Fix: only credit a tier once its extractor
// returns real non-empty text; label the all-failed case explicitly.
let text = '';
let contentCreationSource = null;
try {
  const glmText = extractNimText($('Content Creation').item);
  if (glmText) {
    text = glmText;
    contentCreationSource = 'gpt_oss_nim';
  }
} catch (e) { /* Content Creation (GLM primary) branch didn't run in this execution path */ }
if (!text) {
  try {
    const geminiText = extractGeminiText($('Content Creation Fallback (Gemini)').item);
    if (geminiText) {
      text = geminiText;
      contentCreationSource = 'gemini_fallback';
    }
  } catch (e) { /* Gemini fallback branch didn't run */ }
}
if (!contentCreationSource) {
  contentCreationSource = 'all_tiers_failed';
}
return [{
  json: {
    content: { parts: [{ text }] },
    contentCreationSource,
  },
}];

