    reelScriptSource = 'gpt_oss_nim';
  }
} catch (e) { /* NIM primary branch didn't run in this execution path */ }
if (!raw) {
  try {
    const geminiText = extractGeminiText($('Reel Script Designer Fallback (Gemini)').item);
    if (geminiText) {
      raw = geminiText;
      reelScriptSource = 'gemini_fallback';
    }
  } catch (e) { /* Gemini fallback branch didn't run */ }
}
if (!reelScriptSource) {
  reelScriptSource = 'all_tiers_failed';
}

const parsed = parseJsonLoose(raw);

const SOFT_CAP_SECONDS = 60; // default assumption, not a firm platform limit - flagged, not enforced
const OVER_CAP_FLAG_SECONDS = 75; // 25% grace before flagging as a real overrun

const rawBeats = (parsed && Array.isArray(parsed.beats)) ? parsed.beats : [];

// De-dupe by beat_number (observed live: the model can repeat a beat verbatim under the same
// beat_number) and re-number sequentially so downstream consumers always get a clean 1..N list.
const seenBeatNumbers = new Set();
const dedupedRawBeats = [];
let duplicateBeatsDropped = 0;
for (const b of rawBeats) {
  const key = Number.isFinite(b.beat_number) ? b.beat_number : dedupedRawBeats.length + 1;
  if (seenBeatNumbers.has(key)) {
    duplicateBeatsDropped += 1;
    continue;
  }
  seenBeatNumbers.add(key);
  dedupedRawBeats.push(b);
}

const beats = dedupedRawBeats.map((b, i) => ({
  beatNumber: i + 1,
  durationSeconds: Number(b.duration_seconds) || 0,
  visualDirection: b.visual_direction || '',
  onScreenTextAr: b.on_screen_text_ar || '',
  voAr: b.vo_ar || '',
  voTone: b.vo_tone || '',
}));

// Always computed from the final (deduped) beat list, not trusted from the model's own
// self-reported total_duration_seconds, which can't be more correct than the beats it summed.
const totalDuration = beats.reduce((sum, b) => sum + b.durationSeconds, 0);

const draft = $('Parse AI Draft').item.json;

return [{
  json: {
    ...draft,
    reelScriptGenerationFailed: !parsed || beats.length === 0,
    reelScriptSource,
    reelScriptBeats: beats,
    reelScriptBeatCount: beats.length,
    reelScriptDuplicateBeatsDropped: duplicateBeatsDropped,
    reelScriptTotalDurationSeconds: totalDuration,
    reelScriptDurationCapExceeded: totalDuration > SOFT_CAP_SECONDS,
    reelScriptDurationSeriouslyOver: totalDuration > OVER_CAP_FLAG_SECONDS,
    reelScriptCaptionAr: (parsed && parsed.caption_ar) || '',
    reelScriptCaptionEn: (parsed && parsed.caption_en) || '',
    reelScriptCoverAltTextAr: (parsed && parsed.cover_alt_text_ar) || '',
    reelScriptRaw: raw,
  },
}];

